# Lambda and Nebius blog posts on MLPerf Inference v5.1, held against the v5.0 and v5.1 result files. python3 -I check_claims_v51_posts.py
import json,hashlib,re
FILES=['raw/inf_5.0.json','raw/inf_5.1.json']; RAW={f:open(f,'rb').read() for f in FILES}
V0=json.loads(RAW[FILES[0]]); V1=json.loads(RAW[FILES[1]]); s=str; pc=lambda x,y:100*(x/y-1); P=lambda x:x['Performance_Result']
def n(x):
    m=re.findall(r'\(x(\d+)\)',s(x.get('Accelerator'))); 
    return sum(map(int,m)) if m else int(x.get('a#') or 0)*int(x.get('Nodes') or 1)
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=calc,stated=st,delivered=got,outcome=out,note=note,label_mismatch=False)
D0=[x for x in V0 if x['Category']=='closed' and 'datacenter' in x['Suite']]; D1=[x for x in V1 if x['Category']=='closed' and 'datacenter' in x['Suite']]
def one(L,sub,m,sc,contains=''):
    r=[x for x in L if x['Submitter']==sub and x['Model']==m and x['Scenario']==sc and contains in x['System']]; assert len(r)==1,(sub,m,sc,contains,len(r)); return P(r[0])
def best(L,m,sc,acc,cnt):
    r=[x for x in L if x['Model']==m and x['Scenario']==sc and acc in s(x['Accelerator']) and n(x)==cnt]; return max(r,key=P)
LA=[];NB=[]
rows=[('llama2-70b-99','Offline'),('llama2-70b-99','Server'),('llama3.1-405b','Offline'),('llama3.1-405b','Server'),('stable-diffusion-xl','Offline'),('stable-diffusion-xl','Server')]
st=[(102725.0,98858.0,3.9),(99993.9,98443.3,1.6),(1648.6,1538.17,7.2),(1246.79,1080.31,15.4),(32.57,30.38,7.2),(28.46,28.92,-1.6)]
lam=[one(D1,'Lambda',m,sc) for m,sc in rows]; b0=[P(best(D0,m,sc,'B200',8)) for m,sc in rows]
ok=all(abs(l-a[0])/a[0]<0.0006 and abs(b-a[1])/a[1]<0.0006 and abs(pc(l,b)-a[2])<0.06 for l,b,a in zip(lam,b0,st))
LA.append(mk('LV1','Lambda results table in the post, v5.1 result against v5.0 best for six model and scenario rows','Lambda entry 5.1-0060 (8 x B200) against the best 8 x B200 entry in v5.0 for each row','six rows, deltas +3.9, +1.6, +7.2, +15.4, +7.2 and -1.6 percent','; '.join(f'{m} {sc}: {l:,.2f} against {b:,.2f} ({pc(l,b):+.1f}%)' for (m,sc),l,b in zip(rows,lam,b0)),'CONSISTENT' if ok else 'BELOW','The v5.0 best is the best 8 x B200 entry. A MangoBoost 8-accelerator entry is higher in Llama 2 70B Offline at 103,182.'))
pos=sum(1 for l,b in zip(lam,b0) if l>b)
LA.append(mk('LV2','Five of six submissions delivered higher performance than the prior rounds, with gains ranging from +1.6% to +15.4%','same six rows','five of six higher, +1.6% to +15.4%',f'{pos} of 6 higher. Gains {min(pc(l,b) for l,b in zip(lam,b0) if l>b):+.1f}% to {max(pc(l,b) for l,b in zip(lam,b0)):+.1f}%','CONSISTENT' if pos==5 else 'BELOW',''))
hb={(m,sc):best(D1,m,sc,'H200',8) for m,sc in rows}
r={k:P(next(x for x in D1 if x['Submitter']=='Lambda' and x['Model']==k[0] and x['Scenario']==k[1]))/P(v) for k,v in hb.items()}
LA.append(mk('LV3','On 8xB200, both Llama 3.1 405B and Llama 2 70B delivered 3-4x higher performance than the best 8xH200 results','Lambda 8 x B200 entry against the best 8 x H200 entry in v5.1, Llama 3.1 405B and Llama 2 70B 99','3-4x higher',', '.join(f'{k[0]} {k[1]} {v:.2f}x ({hb[k]["Submitter"]})' for k,v in r.items() if k[0].startswith('llama')),'CONSISTENT' if all(2.9<=v<=4.3 for k,v in r.items() if k[0].startswith('llama')) else 'BELOW','The ratios are 2.9 to 4.2. The two Llama 2 70B ratios are 2.9.'))
sd=r[('stable-diffusion-xl','Offline')]
LA.append(mk('LV4','SDXL was 1.07x faster than the best 8xH200 results','Lambda 8 x B200 SDXL entry against the best 8 x H200 SDXL entry in v5.1',f'1.07x',f'Offline {r[("stable-diffusion-xl","Offline")]:.2f}x ({hb[("stable-diffusion-xl","Offline")]["Submitter"]} {P(hb[("stable-diffusion-xl","Offline")]):.2f}), Server {r[("stable-diffusion-xl","Server")]:.2f}x ({hb[("stable-diffusion-xl","Server")]["Submitter"]} {P(hb[("stable-diffusion-xl","Server")]):.2f})','CONSISTENT' if any(abs(v-1.07)<0.015 for k,v in r.items() if k[0].startswith('stable')) else 'ABOVE','The statement does not say which scenario. The 1.07x equals the Offline gain over the v5.0 best 8 x B200 entry (32.57 over 30.38), not the gain over the best 8 x H200 entry.'))
lr=[x for x in D1 if x['Submitter']=='Lambda'][0]
LA.append(mk('LV5','Host CPU : Dual Intel Xeon Platinum 8750 with 56 cores','host processor fields of Lambda entry 5.1-0060','dual Xeon Platinum 8750, 56 cores',f'{s(lr["Processor"])}, {lr["host_processors_per_node"]} per node, {lr["host_processor_core_count"]} cores each','CONSISTENT' if int(lr['host_processors_per_node'])==2 and int(lr['host_processor_core_count'])==56 else 'BELOW','The post writes 8750. The file lists 8570.'))
LA.append(mk('LV6','Lambda placed first or second in rankings across three MLPerf categories, standing out among a dozen top vendors','Lambda ranks among 8 x B200 entries in v5.1, per model and scenario',"first or second in three categories",'; '.join(f'{m} {sc}: rank {1+sum(1 for x in D1 if x["Model"]==m and x["Scenario"]==sc and "B200" in s(x["Accelerator"]) and n(x)==8 and P(x)>l)} of {sum(1 for x in D1 if x["Model"]==m and x["Scenario"]==sc and "B200" in s(x["Accelerator"]) and n(x)==8)}' for (m,sc),l in zip(rows,lam)),'CANNOT_TELL','The post does not name its categories or its group of vendors. Lambda is first or second in three of the six rows within the 8 x B200 group.'))
LA.append(mk('LV7','using NVIDIA TensorRT 10.11 on NVIDIA CUDA 12.9','software field of Lambda entry 5.1-0060','TensorRT 10.11, CUDA 12.9',s(lr['Software']),'CONSISTENT' if 'TensorRT 10.11' in s(lr['Software']) and '12.9' in s(lr['Software']) else 'BELOW',''))
# Nebius
g=lambda sc:one(D1,'Nebius','llama3.1-405b',sc,'Nebius GB200'); g0={'Offline':801.906,'Server':522.12}
gp=[x for x in D0 if x['Model']=='llama3.1-405b' and 'GB200' in s(x['System'])+s(x['Accelerator']) and n(x)==4]
gb0={sc:max(P(x) for x in gp if x['Scenario']==sc) for sc in ('Offline','Server')}
NB.append(mk('NE1','compared to the best results of the previous round, our one-host installation achieved 6.7% and 14.2% performance increases running Llama 3.1 405B inference in offline and server modes, respectively','Nebius 4-GPU GB200 entry 5.1-0074 against the best 4-GPU GB200 entries in v5.0, Llama 3.1 405B','+6.7% Offline, +14.2% Server',f'Offline {g("Offline"):,.2f} against {gb0["Offline"]:,.2f} ({pc(g("Offline"),gb0["Offline"]):+.1f}%). Server {g("Server"):,.2f} against {gb0["Server"]:,.2f} ({pc(g("Server"),gb0["Server"]):+.1f}%)','CONSISTENT' if abs(pc(g("Offline"),gb0["Offline"])-6.7)<0.06 and abs(pc(g("Server"),gb0["Server"])-14.2)<0.06 else 'BELOW','The v5.0 best is a 4-GPU GB200 entry from CoreWeave. A 72-GPU NVIDIA entry is far higher in both rounds.'))
grp=[x for x in D1 if x['Model']=='llama3.1-405b' and 'GB200' in s(x['System'])+s(x['Accelerator']) and n(x)==4]
NB.append(mk('NE2','These two numbers also hold the first place for Nebius, among other ... Inference v5.1 submitters for this model on GB200 systems','4-GPU GB200 entries in v5.1, Llama 3.1 405B','first place among v5.1 submitters on GB200','; '.join(f'{x["Submitter"]} {x["Scenario"]} {P(x):,.2f}' for x in sorted(grp,key=lambda x:(x['Scenario'],-P(x))) if x['Scenario'] in('Offline','Server')),'CONSISTENT' if all(max((x for x in grp if x['Scenario']==sc),key=P)['Submitter']=='Nebius' for sc in('Offline','Server')) else 'BELOW','The group is the 4-GPU entries. The 72-GPU NVIDIA entries are higher.'))
h=lambda m,sc:one(D1,'Nebius',m,sc,'Nebius H200'); b2=lambda m,sc:one(D1,'Nebius',m,sc,'Nebius B200')
NB.append(mk('NE3','one host with 4x Blackwell GPUs achieved a 54.8% performance gain compared to an H200 host powered by 8x GPUs, while normalized per-chip comparison showed a 3.1x performance increase','Nebius GB200 4-GPU entry against Nebius H200 8-GPU entry, Llama 3.1 405B Offline','+54.8% per host, 3.1x per chip',f'{g("Offline"):,.2f} against {h("llama3.1-405b","Offline"):,.2f} ({pc(g("Offline"),h("llama3.1-405b","Offline")):+.1f}%), per chip {(g("Offline")/4)/(h("llama3.1-405b","Offline")/8):.2f}x','CONSISTENT' if abs(pc(g("Offline"),h("llama3.1-405b","Offline"))-54.8)<0.1 and abs((g("Offline")/4)/(h("llama3.1-405b","Offline")/8)-3.1)<0.06 else 'BELOW',''))
NB.append(mk('NE4','Running Llama 3.1 405B inference on NVIDIA HGX B200, we recorded 1,660 tokens/s in offline mode and 1,280 tokens/s in server scenario','Nebius B200 8-GPU entry 5.1-0073, Llama 3.1 405B','1,660 and 1,280',f'{b2("llama3.1-405b","Offline"):,.1f} and {b2("llama3.1-405b","Server"):,.1f}','CONSISTENT' if round(b2("llama3.1-405b","Offline"),-1)==1660 and round(b2("llama3.1-405b","Server"),-1)==1280 else 'BELOW','Rounded to the nearest ten.'))
NB.append(mk('NE5','we see 3x and 4.3x performance increases in offline and server scenarios respectively','Nebius B200 entry against Nebius H200 entry, Llama 3.1 405B','3x Offline, 4.3x Server',f'{b2("llama3.1-405b","Offline")/h("llama3.1-405b","Offline"):.2f}x Offline, {b2("llama3.1-405b","Server")/h("llama3.1-405b","Server"):.2f}x Server','CONSISTENT' if abs(b2("llama3.1-405b","Offline")/h("llama3.1-405b","Offline")-3)<0.05 and abs(b2("llama3.1-405b","Server")/h("llama3.1-405b","Server")-4.3)<0.05 else 'BELOW',''))
NB.append(mk('NE6','The B200 system outperforms the H200 3x and 2.9x times , by delivering 101,611 and 101,246 tokens/s in server and offline modes, respectively','Nebius B200 and H200 entries, Llama 2 70B 99','3x Server, 2.9x Offline, 101,611 and 101,246',f'Server {b2("llama2-70b-99","Server"):,.0f} ({b2("llama2-70b-99","Server")/h("llama2-70b-99","Server"):.2f}x), Offline {b2("llama2-70b-99","Offline"):,.0f} ({b2("llama2-70b-99","Offline")/h("llama2-70b-99","Offline"):.2f}x)','CONSISTENT' if round(b2("llama2-70b-99","Server"))==101611 and round(b2("llama2-70b-99","Offline"))==101246 and abs(b2("llama2-70b-99","Server")/h("llama2-70b-99","Server")-3)<0.05 and abs(b2("llama2-70b-99","Offline")/h("llama2-70b-99","Offline")-2.9)<0.05 else 'BELOW',''))
def rank(m,sc,acc,v): 
    g_=[x for x in D1 if x['Model']==m and x['Scenario']==sc and acc in s(x['Accelerator']) and n(x)==8]; return 1+sum(1 for x in g_ if P(x)>v),len(g_)
rk=[(m,sc,acc,rank(m,sc,acc,one(D1,'Nebius',m,sc,'Nebius '+acc))) for m in('llama2-70b-99','llama3.1-405b') for sc in('Server','Offline','Interactive') for acc in('B200','H200')]
NB.append(mk('NE7','For both models, Nebius demonstrated the best performance results in server mode , while in offline and interactive scenarios it shows parity with other submitters.','Nebius 8-GPU B200 and H200 entries ranked within the 8-GPU entries of the same accelerator, v5.1','best in Server, parity in Offline and Interactive','; '.join(f'{m} {sc} {acc}: rank {a_} of {b_}' for m,sc,acc,(a_,b_) in rk),'CANNOT_TELL','Parity is not defined. Nebius is first in some Server rows and not in others.'))
h1=lambda sc:P(best(D0,'llama2-70b-99',sc,'H100',8))
NB.append(mk('NE8','Llama 70B inference on HGX H200 systems gives 11% performance increase compared to the best results achieved on H100-powered systems from the MLPerf ... Inference v5.0 submission','Nebius H200 8-GPU entry against the best 8-GPU H100 entry in v5.0, Llama 2 70B 99','+11%',f'Offline {h("llama2-70b-99","Offline"):,.0f} against {h1("Offline"):,.0f} ({pc(h("llama2-70b-99","Offline"),h1("Offline")):+.1f}%). Server {h("llama2-70b-99","Server"):,.0f} against {h1("Server"):,.0f} ({pc(h("llama2-70b-99","Server"),h1("Server")):+.1f}%)','CONSISTENT' if abs(pc(h("llama2-70b-99","Offline"),h1("Offline"))-11)<0.6 else 'BELOW','The 11% reproduces for Offline. Server is 9.4%.'))
for nm,L in (('claims_lambda_v51.json',LA),('claims_nebius_v51.json',NB)):
    json.dump(dict(source=FILES,sha256=[hashlib.sha256(RAW[f]).hexdigest() for f in FILES],claims=L),open(nm,'w'),indent=1)
    for c in L: print(c['id'],c['outcome'],'|',c['stated'][:48],'|',c['delivered'][:230])
